import { emptyRecipe } from "../../src/domain/model/recipe.ts";
import type { AssistantReplyAction, TimelineItem } from "../../src/domain/model/api.ts";
import { measurementKindSpecs, type MeasurementKind } from "../../src/domain/model/brewing.ts";
import { makeBatch, sunsetSplits } from "../helpers/batch.ts";

export type EvalContext = "day0" | "day4" | "splits" | "logged" | "corrected" | "mash" | "stable";
export interface ExpectedReading {
  measurementKind: MeasurementKind;
  value: number;
  unit: string;
  splitId?: string | null;
  sampleTempC?: number;
}
export interface AssistantIntentCase {
  id: string;
  category: "intent" | "splits" | "followup" | "correction" | "timing" | "measurements";
  question: string;
  context?: EvalContext;
  /** Scripted prior turns: identical for all profiles, not generated by a different model. */
  history?: { role: "user" | "assistant"; content: string }[];
  expectedReadings: ExpectedReading[];
  allowedOptionalEvents?: ("comment")[];
  /** The fixture brief does not give the plan detail these questions need. */
  requiresPlan?: boolean;
  review: string;
}
const temperature = (value = 18, splitId: string | null = null): ExpectedReading => ({ measurementKind: "temperature", value, unit: "°C", splitId });

