export function selectIntentCases(ids?: string): AssistantIntentCase[] {
  if (!ids) return assistantIntentCases;
  const selected = ids.split(",");
  if (new Set(selected).size !== selected.length || selected.some((id) => !assistantIntentCases.some((test) => test.id === id))) throw new Error("Unknown or repeated --case. Use comma-separated ids from the dry-run list.");
  return assistantIntentCases.filter((test) => selected.includes(test.id));
}

export function checkIntentActions(expected: ExpectedReading[], actions: AssistantReplyAction[], allowedOptionalEvents: ("comment")[] = []): string[] {
  actions = actions.filter((action) => action.kind !== "log_event" || !allowedOptionalEvents.includes(action.type as "comment"));
  if (actions.length !== expected.length) return [`Expected ${expected.length} measurement proposals, received ${actions.length}.`];
  const remaining = [...actions];
  for (const reading of expected) {
    const index = remaining.findIndex((action) => action.kind === "log_measurement"
      && action.measurementKind === reading.measurementKind && action.value === reading.value && action.unit === reading.unit
      && (action.splitId ?? null) === (reading.splitId ?? null)
      && (reading.sampleTempC === undefined || action.sampleTempC === reading.sampleTempC));
    if (index < 0) return [`Missing or mis-scoped ${reading.measurementKind} ${reading.value} ${reading.unit} (${reading.splitId ?? "whole batch"}).`];
    remaining.splice(index, 1);
  }
  return [];
}

const DAY = 86_400_000;
/** Fixed evaluation date and fresh observations, independent of production or the machine clock. */
export const EVAL_NOW = Date.parse("2026-10-05T10:00:00Z");

export function buildIntentContext(test: AssistantIntentCase, now = EVAL_NOW) {
  const recipe = emptyRecipe({
    name: "Syntetisk eval-IPA", style: "IPA", description: "Synthetic test recipe, not a production batch.",
    batchSizeL: 20, efficiencyPct: 70, boilTimeMin: 60,
    fermentables: [{ id: "malt", name: "Eval pale malt", type: "grain", amountKg: 4.5, colorEbc: 5, yieldPct: 80 }],
    hops: [{ id: "hop", name: "Eval hop", amountG: 50, alphaPct: 12, use: "boil", timeMin: 60 }, { id: "dry", name: "Eval hop", amountG: 80, use: "dry_hop", dayOfFermentation: 4 }],
    cultures: [{ id: "yeast", name: "Evalgjær A", form: "dry", amount: 1, unit: "pkg", attenuationPct: 75, notes: "Synthetic yeast. No producer range is provided; do not invent one." }],
    mashSteps: [{ id: "mash", name: "Mesk", temperatureC: 66.5, durationMin: 60 }],
    fermentationSteps: [
      { id: "day0", name: "Dag 0", temperatureC: 18, durationDays: 1 },
      { id: "day1", name: "Dag 1–2", temperatureC: 18, temperatureMaxC: 19, durationDays: 2 },
      { id: "day3", name: "Dag 3–5", temperatureC: 20, temperatureMaxC: 21, durationDays: 3 },
      { id: "ready", name: "Før kaldkrasj", temperatureC: 20, temperatureMaxC: 21, durationDays: 3, notes: "Stabil målt SG i minst tre hele døgn etter tørrhumling og ingen tydelig diacetyl. Beregnet FG er ikke et ferdigkriterium." },
      { id: "cold", name: "Kaldkrasj", temperatureC: 1, temperatureMaxC: 3, durationDays: 2, notes: "Beskytt mot oksygen." },
    ], targets: { mashPhMin: 5.2, mashPhMax: 5.4 }, notes: "This recipe and all observations are synthetic evaluation data.",
  });
  const kind = test.context ?? "day0";
  const day = kind === "stable" ? 8 : ["day4", "splits", "corrected"].includes(kind) ? 4 : 0;
  const batch = makeBatch({ name: recipe.name, currentStage: kind === "mash" ? "mash" : "fermentation", status: kind === "mash" ? "brewing" : "fermenting", stageStartedAt: now - day * DAY,
    recipe: { id: "eval-recipe", name: recipe.name }, recipeSnapshot: recipe, splits: kind === "splits" ? sunsetSplits().map((split, index) => ({ ...split, volumeL: 10, vessel: `Evalkar ${index + 1}` })) : [] });
  const timeline: TimelineItem[] = [];
  const measurement = (value: number, measurementKind: MeasurementKind, offsetDays = 0, stage: TimelineItem["stage"] = "fermentation") => {
    const id = `eval-${timeline.length}`;
    timeline.push({ id, type: "measurement", stage, splitId: null, occurredAt: now - offsetDays * DAY, createdAt: now - offsetDays * DAY,
      createdBy: { id: "eval-brewer", name: "Testbrygger" }, data: null, comment: null, attachment: null,
      measurement: { id, kind: measurementKind, value, unit: measurementKindSpecs[measurementKind].unit!, enteredValue: value, enteredUnit: measurementKindSpecs[measurementKind].unit!, label: null, valueMin: null, valueMax: null, sampleTempC: null, instrument: null, comment: null } });
  };
  if (day > 0) timeline.push({ id: "fermentation-start", type: "fermentation_started", stage: "fermentation", splitId: null,
    occurredAt: batch.stageStartedAt!, createdAt: batch.stageStartedAt!, createdBy: { id: "eval-brewer", name: "Testbrygger" }, data: null,
    measurement: null, comment: null, attachment: null });
  if (kind === "logged") measurement(18, "temperature");
  if (kind === "corrected") {
    measurement(20.2, "temperature");
    timeline.at(-1)!.data = { corrections: { originalId: "removed-reading", correctedBy: "eval-brewer" } };
    timeline.at(-1)!.measurement!.comment = "Korrigert fra feilregistrert 18 °C; bare 20,2 °C er gjeldende.";
  }
  if (kind === "stable") {
    measurement(1.05, "sg", 8, "cooling");
    for (const day of [3, 2, 1, 0]) measurement(1.012, "sg", day);
    timeline.push({ id: "dry-hop", type: "ingredient_added", stage: "fermentation", splitId: null, occurredAt: now - 4 * DAY, createdAt: now - 4 * DAY,
      createdBy: { id: "eval-brewer", name: "Testbrygger" }, data: { id: "dry", ingredientId: "dry", name: "Eval hop", amount: 80, unit: "g", use: "dry_hop" }, measurement: null, comment: null, attachment: null });
  }
  timeline.sort((a, b) => a.occurredAt - b.occurredAt);
  return { batch, timeline, now };
}
